class Solution {
  public int closestValue(TreeNode root, double target) {
    int best = root.val;
    for (TreeNode cur = root; cur != null; cur = target < cur.val ? cur.left : cur.right) {
      double d = Math.abs(cur.val - target), bd = Math.abs(best - target);
      if (d < bd || (d == bd && cur.val < best)) best = cur.val; // ties go to the smaller value
    }
    return best;
  }
}
